from lib import *
S = SS('w23')
steps = [
    step("ping6 ::1 一次,lo0 上的 IPv6 头逐字节:请求的前 40 字节是 60030e00 00103a40 + 16 字节源地址 ::1 + 16 字节目的地址 ::1。第一个字 60030e00:高 4 位版本 6,接着 8 位流量类别 0x00,低 20 位流标签 0x30e00(内核给请求填了一个非零的流标签,应答的流标签是 0);00103a40:载荷长度 16(IPv6 头 40 字节不计在内,载荷长度 16 = 8 字节 ICMPv6 头 + 8 字节数据),下一个头 58(ICMPv6),跳数限制 64。整个包 56 字节 = 40 + 16。IPv6 头里没有校验和,所以 ICMPv6 的校验和要覆盖“伪头部”(源、目的、上层长度、下一个头 58)再加上 ICMPv6 报文:抓到 0x09ca,自己算出 0x09ca,一致。", t=tl(S(1)), mark=lidx(S(1), '请求的前 40 字节', '请求:版本 6', 'ICMPv6 校验和'), done=lidx(S(1), '应答:版本 6', 'ICMPv6 的校验和覆盖伪头部'), kv=KV([['固定头', '40 字节(IPv4 是 20 + 选项)'], ['版本 / 流量类别 / 流标签', '4 / 8 / 20 位'], ['载荷长度', '16(不含 40 字节的头)'], ['下一个头', '58 = ICMPv6'], ['跳数限制', '64(相当于 IPv4 的 TTL)'], ['头校验和', '没有']], ['头校验和'])),
    step("开销对比:ping 127.0.0.1 的 IP 总长 84 字节(20 + 8 + 56 字节载荷),ping6 ::1 是 56 字节(40 + 8 + 8 字节载荷),两个 ping 默认载荷不同,总长不能直接比;每个包的 IP 头 IPv4 是 20 字节(无选项时),IPv6 固定 40 字节,多 20 字节。下载 1 MiB(1048576 字节):IPv4 在 lo0 上 109 个包,SYN 通告 MSS 16344,所有包的 IP + TCP 头合计 5692 字节,占 0.54%;IPv6 107 个包,MSS 16324,头合计 7728 字节,占 0.73%。MSS 差正好 20 字节。在 lo0 这种大 MTU 上头部开销都小于 1%。", t=tl(S(2)), mark=lidx(S(2), 'ping 127.0.0.1', 'MSS 差'), done=lidx(S(2), 'IPv4:下载', 'IPv6:下载'), b=bars([['IPv4 · 头部占比', 0.54, '0.54%'], ['IPv6 · 头部占比', 0.73, '0.73%']], 0.8, mark=[1], done=[0]), kv=KV([['IP 头', 'IPv4 20 字节 / IPv6 40 字节'], ['MSS(lo0)', '16344 对 16324,差 20'], ['1 MiB 下载', '头部占 0.54% 对 0.73%']], ['MSS(lo0)'])),
    step("流量类别与流标签:IPV6_TCLASS 设成 0xb8,线上流量类别就是 0xb8(和 IPv4 的 TOS 一样,DSCP 在高 6 位)。流标签是发送方内核自己填的:6 个不同的 UDP 套接字各发 4 个包,同一个套接字的 4 个包流标签相同,不同套接字互不相同(0xf0d00、0xa0900、0xd0d00、0x20000、0xd0000、0x50200),都不是 0;设 TCLASS 的套接字两个包的流标签也相同(0xd0100)。也就是说内核用流标签标记“同一个套接字的一条流”,路由器可以据此做负载均衡,而不必解析上层端口。", t=tl(S(3)), mark=lidx(S(3), '设 IPV6_TCLASS', '6 个不同套接字'), done=lidx(S(3), '套接字 1', '套接字 2', '套接字 3', '套接字 4', '套接字 5', '套接字 6'), kv=KV([['IPV6_TCLASS 0xb8', '线上流量类别 0xb8'], ['流标签', '20 位,内核按套接字生成,不为 0'], ['同一套接字', '4 个包流标签相同'], ['不同套接字', '互不相同']], ['流标签'])),
    step("真实局域网上的 IPv6 包:en0 抓 25 秒共 275 个 IPv6 包,全部是本地链路的流量(别的设备的流量只统计个数):UDP 且跳数限制 255 的 184 个、UDP 且跳数限制 1 的 87 个、ICMPv6 且跳数限制 255 的 4 个;目的地址 ff02::fb(mDNS 组播)271 个,单播 4 个。跳数限制只有 255 和 1 两种,没有 64 或 128:本地链路协议不会被路由出去。邻居发现等 ICMPv6 要求跳数限制 255,以证明包没有经过路由器;这里的 4 个 ICMPv6 就是 255。", t=tl(S(4)), mark=lidx(S(4), '跳数限制 255:184', '跳数限制 1:87', '下一个头 58'), done=lidx(S(4), '25 秒共', '目的地址类别', '这 25 秒里'), b=bars([['UDP · 跳数限制 255', 184, '184'], ['UDP · 跳数限制 1', 87, '87'], ['ICMPv6 · 跳数限制 255', 4, '4']], 184, mark=[2], done=[0, 1]), kv=KV([['25 秒', '275 个 IPv6 包'], ['目的', 'ff02::fb(mDNS)271 个'], ['跳数限制', '只有 255 与 1'], ['ICMPv6', '4 个,跳数限制 255']], ['跳数限制'])),
    step("扩展头链(手工构造,不是抓来的):逐跳选项 8 字节(含路由器警告)→ 路由头 24 字节(类型 2)→ 分片头 8 字节 → 目的选项 8 字节 → UDP 13 字节,加上 40 字节的 IPv6 头共 101 字节,IPv6 头里的载荷长度是 61(包含所有扩展头)。tcpdump 解出 HBH (rtalert) (padn) RT6 (len=2, type=2, segleft=1) frag (0xdeadbeef:0|21) DSTOPT (padn) 40000 > 9: UDP;自己沿“下一个头”字段走得到同样的链;scapy 解出 IPv6 / HopByHop / Routing / Fragment / DestOpt / UDP。扩展头合计 48 字节。每个头的 8 位“下一个头”指向后一个,这就是链;逐跳选项必须紧跟在 IPv6 头后面,因为沿途每个路由器都要检查它。普通套接字发不出这类扩展头(用 sendmsg 发逐跳选项时返回 Permission denied),所以这里是构造而不是抓包。", t=tl(S(5)), mark=lidx(S(5), 'tcpdump 解码', '自己沿下一个头走', 'scapy 解码出的层'), done=lidx(S(5), '构造的包', '扩展头合计'), kv=KV([['链', '每个头的“下一个头”指向后一个'], ['101 字节', '40 + 8 + 24 + 8 + 8 + 13'], ['载荷长度', '61,含全部扩展头'], ['逐跳选项', '必须紧跟 IPv6 头']], ['链'])),
]
A = mkartw('w23', 23, '网络协议,IPv6,IPv6头,扩展头,流标签,跳数限制,真实验证,动画演示',
    '逐字节解码 lo0 上的 IPv6 头(40 字节固定,无校验和,ICMPv6 校验和覆盖伪头部);IPv6 头比 IPv4 头多 20 字节、MSS 差 20;流标签由内核按套接字生成;en0 上 25 秒 275 个 IPv6 包的跳数限制只有 255 与 1;手工构造的扩展头链用 tcpdump 与 scapy 解码。',
    'IPv6 的头为什么是固定 40 字节?没有了校验和、选项和分片字段,这些东西去了哪里?这篇在 lo0 上抓 ping6 的真实 IPv6 头逐字节解码,看流标签和跳数限制,再手工拼一个带扩展头链的包让 tcpdump 和 scapy 一起解码。',
    [('40 字节', 'IPv6 头固定大小,比 IPv4 的 20 字节(无选项)多 20 字节;下载同样 1 MiB,头部占 0.73% 对 0.54%'), ('0x30e00', '内核给 ping6 请求填的非零流标签(20 位);同一个套接字的包流标签相同'), ('255 与 1', '本机局域网上 25 秒 275 个 IPv6 包的跳数限制只有这两种取值')],
    [('固定头', '<p>版本 4 位、流量类别 8 位、流标签 20 位、载荷长度 16 位、下一个头 8 位、跳数限制 8 位,再加 16 字节源和 16 字节目的地址,共 40 字节。没有头校验和、没有分片字段,路由器每转发一次只需把跳数限制减 1。</p>'),
     ('校验和去哪了', '<p>IPv6 头没有校验和,上层的 ICMPv6、TCP、UDP 校验和要覆盖包含源 / 目的地址的伪头部。自己按伪头部算出的 ICMPv6 校验和与抓到的值一致。</p>'),
     ('流标签与流量类别', '<p>流量类别与 IPv4 的 TOS 用法相同;流标签是内核按套接字生成的 20 位值,同一个套接字的包相同,路由器可据此识别一条流。</p>'),
     ('本地链路上的 IPv6', '<p>局域网上的 IPv6 流量(mDNS、邻居发现)跳数限制是 255 或 1,不出本地链路。</p>'),
     ('扩展头', '<p>IPv4 的选项和分片字段在 IPv6 里变成可选的扩展头,按“下一个头”串成链;逐跳选项必须紧跟 IPv6 头。这一节是手工构造的包,用 tcpdump、scapy 和自己的解析程序互相验证。</p>')],
    steps,
    [ENV_W + '。本机网络没有公网 IPv6(en0 只有链路本地地址),所以第一至三节在 lo0 上用 ::1 做真实抓包,第四节抓的是 en0 上的本地链路 IPv6 流量(别的设备的包只统计个数);第五节是手工构造的包(地址为文档前缀 2001:db8::/32),不是抓来的',
     '没有验证:公网上的 IPv6 路径(本机没有 IPv6 路由);MLD 报文里的逐跳选项(加入组播组时没有抓到 MLD 报告);分片头在真实传输中的出现(lo0 不分片);IPv6 路由头类型 0 的弃用与安全问题;流标签在路由器上被用来做负载均衡的实际效果'],
    'IPv6 头部')
